@use 'classicy/scss/appearance';

.split {
	display: flex;
	height: 100%;
	min-height: 0;
}

.list {
	width: 190px;
	flex-shrink: 0;
	margin: 0;
	padding: 0;
	list-style: none;
	overflow-y: auto;
	border-right: 1px solid var(--color-theme-05);
	background: var(--color-theme-01);
}

.row,
.rowSelected {
	display: block;
	width: 100%;
	padding: 6px 8px;
	border: none;
	border-bottom: 1px solid var(--color-theme-05);
	background: none;
	text-align: left;
	cursor: pointer;
	font-family: inherit;
}

.rowSelected {
	background: var(--color-theme-06);
	color: var(--color-theme-01);
}

.headline {
	display: flex;
	align-items: center;
	gap: var(--windows-padding-size);
	font-weight: bold;
	font-family: var(--ui-font);
	font-size: var(--ui-font-size);
}

// Featured star, sized to match the headline text height (1em of the headline).
.star {
	height: 1em;
	width: auto;
	flex-shrink: 0;
}

.byline {
	display: block;
	opacity: 0.75;
	margin-top: calc(var(--windows-border-size) *2);
	font-family: var(--ui-font);
	font-size: var(--ui-font-size);
}

.body {
	flex: 1;
	min-width: 0;
	overflow-y: auto;
	padding: 10px 14px;
}

// The article headline, repeated at the top of the reading pane in the theme's
// body/display font.
.bodyHeadline {
	margin: 0 0 8px;
	font-size: var(--header-font-size);
	font-family: var(--header-font);
	font-weight: bold;
	line-height: 1.15;
}

// The article copy, in the theme's UI font.
.bodyText {
	font-family: var(--ui-font);
	font-size: var(--ui-font-size);

	img {
		max-width: 100%;
	}
}

.status {
	padding: 12px;
	font-size: 12px;
}

.pills {
	display: flex;
	flex-wrap: wrap;
	margin-top: calc(var(--windows-border-size) * 2);
	gap: var(--window-padding-size);
}

.pill {
	display: inline-block;
	padding: 1px 6px;
	border-radius: 8px;
	font-family: var(--ui-font);
	font-size: calc(var(--ui-font-size) * 0.85);
	line-height: 1.4;
	white-space: nowrap;
}

.settings {
	display: flex;
	flex-direction: column;
	padding: var(--window-padding-size);
	gap: var(--window-padding-size);
	font-family: var(--ui-font);
	font-size: var(--ui-font-size);
	background-color: var(--color-system-02);
}

.settingsButtons {
	display: flex;
	flex-direction: row;
	justify-content: flex-end;
	gap: calc(var(--window-padding-size) * 0.5);
	padding-top: calc(var(--window-padding-size) * 0.5);
}
